  --   'campaign__channel',
  --   'campaign__market',
  --   'lead__campaign__campaign_name',
  --   'lead__campaign__channel',
  --   'lead__campaign__market',
  --   'lead__country',
  --   'metric_time__day',
  -- ]
  -- Aggregate Inputs for Simple Metrics
  -- Compute Metrics via Expressions
  -- Write to DataTable
  WITH rss_10006_cte AS (
    -- Read Elements From Semantic Model 'campaigns'
    SELECT
      channel
      , market
      , name AS campaign_name
      , campaign_id AS campaign
    FROM {{ ref('slv_campaigns') }} campaigns_src_10000
  )

  SELECT
    subq_37.metric_time__day AS metric_time__day
    , subq_43.country AS lead__country
    , subq_43.campaign__channel AS lead__campaign__channel
    , subq_43.campaign__market AS lead__campaign__market
    , subq_43.campaign__campaign_name AS lead__campaign__campaign_name
    , rss_10006_cte.channel AS campaign__channel
    , rss_10006_cte.market AS campaign__market
    , rss_10006_cte.campaign_name AS campaign__campaign_name
    , SUM(subq_37.__booking_value_eur) AS booking_value_eur
    , SUM(subq_37.__bookings) AS bookings
  FROM (
    -- Read Elements From Semantic Model 'bookings'
    -- Metric Time Dimension 'booked_date'
    SELECT
      TIMESTAMP_TRUNC(booked_date, day) AS metric_time__day
      , lead_id AS lead
      , campaign_id AS campaign
      , 1 AS __bookings
      , amount AS __booking_value_eur
    FROM {{ ref('slv_bookings') }} bookings_src_10000
  ) subq_37
  LEFT OUTER JOIN (
